import React, { useState } from "react";
import Login from "./components/Login";

const VIEWS = {
  LIST: "list",
  DETAIL: "detail",
  CREATE: "create",
  EDIT: "edit",
  CALCULATOR: "calculator"
};

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentView, setCurrentView] = useState(VIEWS.LIST);
  const [selectedTripId, setSelectedTripId] = useState(null);

  if (!isLoggedIn) {
    return <Login onLogin={() => setIsLoggedIn(true)} />;
  }

  return (
    <div style={{
      minHeight: "100vh",
      background: "#0f172a",
      fontFamily: "Arial, sans-serif"
    }}>
      <nav style={{
        background: "#1e293b",
        borderBottom: "2px solid #f97316",
        padding: "0 24px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        height: "60px"
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: "32px" }}>
          <span style={{
            fontSize: "20px",
            fontWeight: "700",
            color: "#f97316"
          }}>
            🚛 Freight Planner
          </span>
        </div>
        <button
          onClick={() => setIsLoggedIn(false)}
          style={{
            background: "transparent",
            color: "#94a3b8",
            border: "1px solid #475569",
            padding: "8px 16px",
            borderRadius: "6px",
            cursor: "pointer"
          }}
        >
          Kirjaudu ulos
        </button>
      </nav>

      <div style={{ padding: "24px", maxWidth: "1400px", margin: "0 auto", color: "#f1f5f9" }}>
        <h1 style={{ color: "#f97316" }}>Tervetuloa, demo!</h1>
        <p style={{ color: "#94a3b8" }}>
          Kirjautuminen onnistui! Seuraavaksi rakennetaan keikkalista, kuormat ja kustannuslaskin.
        </p>
      </div>
    </div>
  );
}

export default App;
